<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Profile\Infrastructure\Driver\Html\Panels;

use Civi\Lughauth\Features\OAuth\Profile\Domain\OidcProfile;

/**
 * HTML rendering component for the editable OIDC profile form.
 *
 * This panel produces the HTML fragment used by the ProfileHtml controller when the
 * user requests to edit their profile fields (given name, family name, locale, etc.).
 * It accepts an optional OidcProfile snapshot to pre-populate the form inputs with
 * the current stored values, making it suitable for both initial creation and
 * subsequent edits.
 *
 * The panel is a stateless view component: it performs no domain logic, reads no
 * repositories, and only escapes and formats the data it receives.  All user-visible
 * labels are sourced from the $t translations array supplied by the controller.
 */
class ProfileEditPanel
{
    /**
     * Renders the profile edit form as an HTML string.
     *
     * Pre-populates each input from the $profile snapshot when provided; leaves fields
     * blank for a new profile.  An optional $error message is displayed above the form.
     */
    public function render(?OidcProfile $profile, string $saveUrl, string $cancelUrl, ?string $error = null, array $t = []): string
    {
        $saveUrl = htmlspecialchars($saveUrl);
        $cancelUrl = htmlspecialchars($cancelUrl);
        $errorHtml = $error !== null && $error !== ''
            ? '<p class="error">' . htmlspecialchars($error) . '</p>'
            : '';

        $v = static fn (?string $val): string => htmlspecialchars($val ?? '');

        return <<<HTML
            <h1>{$t['title']}</h1>
            {$errorHtml}
            <form method="POST" action="{$saveUrl}" class="profile-edit-form">
                <label>{$t['givenName']}
                    <input type="text" name="givenName" value="{$v($profile?->givenName)}" />
                </label>
                <label>{$t['familyName']}
                    <input type="text" name="familyName" value="{$v($profile?->familyName)}" />
                </label>
                <label>{$t['middleName']}
                    <input type="text" name="middleName" value="{$v($profile?->middleName)}" />
                </label>
                <label>{$t['nickname']}
                    <input type="text" name="nickname" value="{$v($profile?->nickname)}" />
                </label>
                <label>{$t['preferredUsername']}
                    <input type="text" name="preferredUsername" value="{$v($profile?->preferredUsername)}" />
                </label>
                <label>{$t['pictureUrl']}
                    <input type="url" name="pictureUrl" value="{$v($profile?->pictureUrl)}" />
                </label>
                <label>{$t['website']}
                    <input type="url" name="websiteUrl" value="{$v($profile?->websiteUrl)}" />
                </label>
                <label>{$t['gender']}
                    <input type="text" name="gender" value="{$v($profile?->gender)}" />
                </label>
                <label>{$t['birthdate']}
                    <input type="date" name="birthdate" value="{$v($profile?->birthdate)}" />
                </label>
                <label>{$t['timezone']}
                    <input type="text" name="zoneinfo" value="{$v($profile?->zoneinfo)}" placeholder="Europe/Madrid" />
                </label>
                <label>{$t['locale']}
                    <input type="text" name="locale" value="{$v($profile?->locale)}" placeholder="es-ES" />
                </label>
                <label>{$t['phoneNumber']}
                    <input type="tel" name="phoneNumber" value="{$v($profile?->phoneNumber)}" />
                </label>
                <div class="profile-actions">
                    <input class="primary-button" type="submit" value="{$t['save']}" />
                    <a class="secondary-button" href="{$cancelUrl}">{$t['cancel']}</a>
                </div>
            </form>
            HTML;
    }
}
